// ===============================
// FUNCIONES
// ===============================

// Función para extraer información de las preguntas
function parsePreguntas(query) {
  const result = {
    formaPago: '',
    autoEntregado: '',
    comentarios: ''
  };

  if (!query) return result;

  // Forma de pago
  if (query.pago) {
    const pago = query.pago.toLowerCase();
    if (pago.includes('contado')) result.formaPago = 'contado';
    else if (pago.includes('financiado')) result.formaPago = 'financiado';
    else if (pago.includes('plan')) result.formaPago = 'plan';
  }

  // Usado
  if (query.usado) {
    const usado = query.usado.toLowerCase();
    if (usado.includes('no') || usado.includes('sin')) result.autoEntregado = 'No';
    else result.autoEntregado = 'Sí';
  }

  // Comentarios
  result.comentarios = `Pago: ${query.pago || ''}, Usado: ${query.usado || ''}`;

  return result;
}

// Función para obtener el código del modelo
function getModeloCode(modeloCompleto) {
  if (!modeloCompleto) return '';

  const modeloLower = modeloCompleto.toLowerCase();

  if (modeloLower.includes('hilux')) return '1';
  if (modeloLower.includes('corolla cross')) return '245';
  if (modeloLower.includes('corolla') && !modeloLower.includes('cross')) return '2';
  if (modeloLower.includes('yaris')) return '227';
  if (modeloLower.includes('etios')) return '225';
  if (modeloLower.includes('sw4')) return '226';
  if (modeloLower.includes('hiace')) return '224';
  if (modeloLower.includes('rav4') || modeloLower.includes('rav 4')) return '3';

  return '';
}

// Función para parsear el modelo
function parseModelo(modeloCompleto) {
  if (!modeloCompleto) return { modelo: '', version: '', modelo_code: '' };

  const palabras = modeloCompleto.trim().split(' ');
  const modelo = palabras[0] || '';
  const version = palabras.slice(1).join(' ') || '';
  const modelo_code = getModeloCode(modeloCompleto);

  return { modelo, version, modelo_code };
}

// Limpiar teléfono
function limpiarTelefono(telefono) {
  if (!telefono) return '';
  let numero = telefono.toString().replace(/\D/g, '');

  if (numero.startsWith('549')) numero = numero.substring(3);
  else if (numero.startsWith('54')) numero = numero.substring(2);

  return numero;
}

// Fuente según interés
function getFuente(interes) {
  if (!interes) return '';
  const i = interes.toLowerCase();
  if (i === 'alto') return 'Redes Sociales Tpa AI';
  if (i === 'bajo') return 'Redes Sociales Tpa BI';
  return '';
}

// Boca de venta según sucursal
function getBocaVenta(sucursal) {
  if (!sucursal) return '';
  const s = sucursal.toLowerCase();

 if (s === 'trenque') return 'TRLA2';
  if (s === 'rosa') return 'STRO';
  if (s === 'pico') return 'GPIC';

  return '';
}

// ===============================
// PROCESAR ENTRADA n8n
// ===============================

const entrada = $input.first().json;
const query = entrada.query || {};

const preguntasInfo = parsePreguntas(query);
const modeloInfo = parseModelo(query.modelo);
const telefonoLimpio = limpiarTelefono(entrada.telefono);

// ===============================
// NORMALIZAR EMAIL + EMAIL_PARSEADO
// ===============================

// Prioridad: entrada.email → query.email → ''
let email = entrada.email || query.email || '';
let email_parseado = '';

if (email && email.toLowerCase() === 'no_especificado') {
  email_parseado = 'no_especificado@gmail.com';
  email = '';
} else {
  email_parseado = email;
}

// ===============================
// FECHA ACTUAL
// ===============================

const fechaActual = new Date().toISOString().split('T')[0];

// ===============================
// NUEVOS CAMPOS
// ===============================

const fuente = getFuente(query.interes || entrada.interes);
const bocaVenta = getBocaVenta(query.sucursal || entrada.sucursal);

// ===============================
// ORIGEN CTA (DUPLICADO)
// ===============================

const origenCTA_original = entrada.origenCTA || query.origenCTA;

const esInvalido = (v) =>
  v === undefined ||
  v === null ||
  v === '' ||
  v === 'undefined' ||
  v === 'null';

let origenCTA;

if (esInvalido(origenCTA_original)) {
  origenCTA = query.pago || '';
} else {
  origenCTA = origenCTA_original;
}

// ===============================
// RESULTADO FINAL
// ===============================

const resultado = {
  requestdate: fechaActual,

  // Datos personales
  nombre: entrada.nombre || '',
  telefono: telefonoLimpio,
  email,
  email_parseado,
  idConversation: entrada.idConversation || '',

  // Vehículo
  modelo: modeloInfo.modelo,
  version: modeloInfo.version,
  modelo_code: modeloInfo.modelo_code,
  marca: 'Toyota',

  // Información de pago
  formaPago: preguntasInfo.formaPago,
  autoEntregado: preguntasInfo.autoEntregado,
  comentarios: preguntasInfo.comentarios,

  // Nuevos campos
  fuente,
  bocaVenta,

  // ORIGEN CTA
  origenCTA,
  origenCTA_original,

  // Campos originales sin tocar
  original: {
    ...entrada
  }
};

// ===============================
// RETURN n8n
// ===============================

return [{ json: resultado }];

