// -----------------------------
// TOMAR ITEM DE ENTRADA
// -----------------------------
const item = $input.first().json;

// Algunos datos vienen dentro de query
const query = item.query || {};

// -----------------------------
// LIMPIAR SALTOS DE LÍNEA EN RESUMEN (si existe)
// -----------------------------
if (item.resumen) {
  item.resumen = item.resumen
    .replace(/\r?\n|\r/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// -----------------------------
// MAPEAR INTERÉS (alto/bajo → high/low)
// -----------------------------
const interesRaw = (query.interes || item.interes || "").toLowerCase();

if (interesRaw === 'alto' || interesRaw === 'alta') {
  item.interes = 'high';
  item.interes_level = 'high';
} else if (interesRaw === 'bajo' || interesRaw === 'baja') {
  item.interes = 'low';
  item.interes_level = 'low';
} else {
  item.interes = null;
  item.interes_level = null;
}

// -----------------------------
// MAPAS DE PRODUCTOS DE INTERÉS
// -----------------------------
const productosInteres = {
  "corolla gr-sport": 68,
  "corolla cross": 69,
  corolla: 67,
  gr86: 70,
  crown: 71,
  "hiace furgón": 72,
  "hiace furgon": 72,
  "hiace wagon": 73,
  "hiace commuter": 74,
  hilux: 75,
  sw4: 76,
  rav4: 77,
  "land cruiser": 78,
  yaris: 79
};

// -----------------------------
// MAPAS DE MÉTODOS DE PAGO
// -----------------------------
const metodosPago = {
  contado: 33,
  financiado: 34,
  "plan de ahorro": 35,
  "no especificado": 36
};

// -----------------------------
// NORMALIZAR CAMPOS
// -----------------------------
const modelo = (query.modelo || "").toLowerCase();
const pago = (query.pago || "").toLowerCase();

// -----------------------------
// OBTENER CÓDIGO DE INTERÉS
// -----------------------------
item.codigo_interes = null;

for (const key in productosInteres) {
  if (modelo.includes(key)) {
    item.codigo_interes = productosInteres[key];
    break;
  }
}

// -----------------------------
// OBTENER CÓDIGO DE PAGO
// -----------------------------
item.codigo_pago = null;

for (const key in metodosPago) {
  if (pago.includes(key)) {
    item.codigo_pago = metodosPago[key];
    break;
  }
}

// -----------------------------
// NORMALIZAR TELÉFONO (si viene con +)
// -----------------------------
if (item.telefono) {
  item.telefono = item.telefono.replace(/\D/g, '');
}

// -----------------------------
// DEVOLVER JSON
// -----------------------------
return [
  {
    json: item
  }
];

const items = $input.all();

for (const item of items) {
  if (item.json.error && item.json.error.message) {
    try {
      const errorMessage = item.json.error.message;

      // Buscar directamente el duplicate_lead_id con regex
      const match = errorMessage.match(/duplicate_lead_id\\":(\d+)/);

      if (match) {
        item.json.duplicate_lead_id = parseInt(match[1]);
      } else {
        item.json.duplicate_lead_id = null;
      }

    } catch (e) {
      console.log('Error:', e.message);
      item.json.duplicate_lead_id = null;
    }
  }
}

return items;

const item = $input.first();

// Verificar si existe assigned_to_user
if (item.json.data && item.json.data.assigned_to_user) {
  return {
    json: {
      assigned_to_user: item.json.data.assigned_to_user,
      mensaje: null
    }
  };
} else {
  return {
    json: {
      assigned_to_user: null,
      mensaje: "Su consulta ya fue registrada. Lo vamos a contactar"
    }
  };
}

// Obtener todos los items de entrada
const items = $input.all();

// Elegir índice aleatorio
const randomIndex = Math.floor(Math.random() * items.length);

// Devolver solo el item elegido
return [
  {
    json: items[randomIndex].json
  }
];

// Obtener todos los items desde Code1
const items = $('Code1').all();

for (const item of items) {
  const resumen = item.json.resumen || '';

  // Helper de extracción segura
  const extract = (label) => {
    const regex = new RegExp(`${label}:\\s*([^\\n]+)`, 'i');
    const match = resumen.match(regex);
    return match ? match[1].trim() : '';
  };

  // -----------------------------
  // EXTRAER CAMPOS REALES
  // -----------------------------
  const nombre = extract('Cliente');
  const email = extract('Email');
  const modeloResumen = extract('Modelo de interés');
  const pagoResumen = extract('Forma de pago');
  const usadoResumen = extract('Vehículo usado');

  // -----------------------------
  // ASIGNAR SOLO SI EXISTE
  // -----------------------------
  if (nombre) item.json.nombre = nombre;
  if (email) item.json.email = email;

  // ⚠️ NO pisar modelo si ya viene cargado
  if (!item.json.modelo && modeloResumen) {
    item.json.modelo = modeloResumen;
  }

  if (pagoResumen) {
    item.json.pago = pagoResumen.toLowerCase();
  }

  if (usadoResumen) {
    item.json.usado = usadoResumen;
  }

  // -----------------------------
  // TIPO (derivado del pago)
  // -----------------------------
  if (item.json.codigo_pago === 27 || item.json.codigo_pago === 28) {
    item.json.tipo = 'convencional';
  } else if (item.json.codigo_pago === 29) {
    item.json.tipo = 'plan';
  } else {
    item.json.tipo = '';
  }
}

return items;
